/**
 * @param {integer} init
 * @return { increment: Function, decrement: Function, reset: Function }
 */
var createCounter = function(init) {
    // Current value, visible only to the three methods below (closure)
    let current = init;

    return {
        increment: () => ++current,        // add 1, return the new value
        decrement: () => --current,        // subtract 1, return the new value
        reset: () => (current = init),     // restore init, return it
    };
};
